function modal(html){let host=byId("layer");if(!host)return;host.innerHTML=`<div class="modalBack"><div class="modal">${html}</div></div>`;wireIdGlobals(host);let back=host.querySelector(".modalBack");if(back)back.onclick=e=>{if(e.target===e.currentTarget)closeM()};host.querySelectorAll("#cx,[data-close]").forEach(b=>{if(!b.onclick)b.onclick=closeM})}function closeM(){let host=byId("layer");if(host)host.innerHTML=""}function confirmDialog({title="Confirmar ação",message="Tem certeza de que deseja continuar?",description="",confirmText="Confirmar",cancelText="Cancelar",danger=false,onConfirm=()=>{}}={}){modal(`<div class="mh"><div><h2>${esc(title)}</h2><p class="sub">${esc(message)}</p></div><button class="x" id="cx">×</button></div>${description?`<div class="${danger?"dangerBox":"card"}" style="margin-top:14px"><p>${esc(description)}</p></div>`:""}<div class="modalActions"><button class="pill" id="dlgCancel">${esc(cancelText)}</button><button class="btn ${danger?"red":""}" id="dlgConfirm">${esc(confirmText)}</button></div>`);let cxEl=byId("cx"),cancelEl=byId("dlgCancel"),confirmEl=byId("dlgConfirm");if(cxEl)cxEl.onclick=closeM;if(cancelEl)cancelEl.onclick=closeM;if(confirmEl)confirmEl.onclick=()=>{closeM();onConfirm()}}function updateGreeting(){let h=new Date().getHours(),g=h<12?"Bom dia":h<18?"Boa tarde":"Boa noite",e=document.querySelector("#greetingText");if(e)e.textContent=g}function daysUntil(s){if(!s)return null;let a=new Date(),b=new Date(s+"T23:59:59");a.setHours(0,0,0,0);return Math.ceil((b-a)/86400000)}function notices(){let a=[];D.missions.forEach(m=>{if(m.done||m.expired||!m.due)return;let d=daysUntil(m.due);if(d<0)a.push({k:"danger",nav:"missions",t:"Missão atrasada",s:`${m.title} • venceu ${m.due.split("-").reverse().join("/")}`});else if(d<=2)a.push({k:"warn",nav:"missions",t:d===0?"Missão vence hoje":"Missão perto do prazo",s:`${m.title} • ${d===0?"hoje":d+" dia(s)"}`})});D.projects.forEach(p=>{if(p.done||!p.due)return;let d=daysUntil(p.due);if(d<0)a.push({k:"danger",nav:"projects",t:"Projeto atrasado",s:`${p.title} • prazo vencido`});else if(d<=7)a.push({k:"warn",nav:"projects",t:d===0?"Projeto vence hoje":"Prazo de projeto próximo",s:`${p.title} • ${d===0?"hoje":d+" dia(s)"}`})});let owner=financeOwnerId();D.finance.expenses.filter(e=>financeOwn(e,owner)&&String(e.status||"pending")!=="paid"&&e.due_date).forEach(e=>{let d=daysUntil(String(e.due_date).slice(0,10));if(d<0)a.push({k:"danger",nav:"finance",t:"Despesa vencida",s:`${e.description} • ${moneyBR(e.amount)}`});else if(d<=2)a.push({k:"warn",nav:"finance",t:d===0?"Despesa vence hoje":"Despesa perto do vencimento",s:`${e.description} • ${moneyBR(e.amount)}`})});return a.slice(0,20)}function renderTopUI(){updateGreeting();let list=notices(),b=document.querySelector("#notifyBadge"),nl=document.querySelector("#notifyList"),tg=document.querySelector("#topThemes");if(b){b.textContent=list.length>9?"9+":list.length;b.classList.toggle("zero",!list.length)}if(nl)nl.innerHTML=list.length?list.map(n=>`<button class="notifyItem ${n.k}" data-notice-nav="${n.nav}"><b>${esc(n.t)}</b><small>${esc(n.s)}</small></button>`).join(""):`<div class="notifyEmpty">Nada urgente por enquanto.</div>`;if(tg){tg.innerHTML=themeList().map(x=>`<button class="topTheme ${D.profile.theme===x[0]?"sel":""}" data-theme-choice="${x[0]}" style="background:${x[2]}"><span>${x[1]}</span></button>`).join("")}}function closePops(){document.querySelectorAll(".headPop.open").forEach(x=>x.classList.remove("open"))}function header(t,s="",extra=""){return`<div class="row between"><div><h1 class="title">${t}</h1><p class="sub">${s}</p></div>${extra}</div>`}
