function missionMinutes(m){if(Number(m?.estimatedMinutes)>0)return Math.round(Number(m.estimatedMinutes));let x=Number(m?.xp||m||0);return x>=170?90:x>=140?60:x>=110?45:x>=85?30:x>=65?20:x>=50?15:10}
