function currentHabitStreak(h){
 let s=0,d=new Date();
 for(let i=0;i<365;i++){
   let k=iso(d);
   if(rest(h,k)){d.setDate(d.getDate()-1);continue}
   if(h.log?.[k])s++; else break;
   d.setDate(d.getDate()-1);
 }
 return s;
}
