function missionCard(m){let mr=missionRank(m),mins=missionMinutes(m),priority=Number(m.aiPriority||0);return`<div class="item missionItem ${m.source==="smart-daily"?"smartDailyMission":""}"><div class="missionRankBadge rank-${mr.toLowerCase()}">${mr}</div><div class="grow"><div class="missionTitleLine"><b>${esc(m.title)}</b>${missionSourceBadge(m)}${priority?`<span class="priorityPill p${priority}">P${priority}</span>`:""}</div><p class="sub">${esc(m.desc||"")}</p>${m.aiReason?`<p class="missionAiReason">✦ ${esc(m.aiReason)}</p>`:""}<div class="missionMeta"><span>⏱ ${mins} min</span><span>ϟ ${m.xp} XP</span>${m.due?`<span>📅 ${esc(m.due.split("-").reverse().join("/"))}</span>`:""}${m.category?`<span>${esc(m.category)}</span>`:""}</div></div><div class="missionActions">${m.targetHabitId?`<button class="pill" data-open-habit="${m.targetHabitId}">Abrir hábito</button>`:""}<button class="btn" data-complete="${m.id}">Concluir</button></div></div>`}
function completedMissionCard(m){let stamp=missionCompletionISO(m),when=stamp?new Intl.DateTimeFormat("pt-BR",{dateStyle:"short",timeStyle:"short"}).format(new Date(stamp)):"Registro anterior",earned=Number(m.earnedXP??m.xp??0);return`<div class="item missionItem completedMissionCard"><div class="completedCheck">✓</div><div class="grow"><div class="missionTitleLine"><b>${esc(m.title)}</b>${missionSourceBadge(m)}</div><p class="sub">${esc(m.desc||"")}</p><div class="missionMeta"><span>Concluída em ${esc(when)}</span><span>ϟ ${earned} XP</span>${m.category?`<span>${esc(m.category)}</span>`:""}</div></div><span class="completedStamp">CONCLUÍDA</span></div>`}
function missions(){ensureSmartDaily();let open=D.missions.filter(m=>!m.done&&!m.expired),daily=open.filter(m=>m.source==="smart-daily"&&m.dailyDate===iso()),active=open.filter(m=>m.source!=="smart-daily").sort((a,b)=>(Number(a.aiPriority||9)-Number(b.aiPriority||9))||String(a.due||"9999").localeCompare(String(b.due||"9999"))),completed=D.missions.filter(m=>m.done).sort((a,b)=>new Date(missionCompletionISO(b)||0)-new Date(missionCompletionISO(a)||0)),recent=completed.filter(missionIsRecent),archived=completed.filter(m=>!missionIsRecent(m)),ai=aiConfig(),perf=dailyPerformance(),tabs=`<div class="missionTabs"><button class="${missionTab==="open"?"on":""}" data-mission-tab="open"><span>Abertas</span><b>${open.length}</b></button><button class="${missionTab==="completed"?"on":""}" data-mission-tab="completed"><span>Concluídas</span><b>${recent.length}</b></button></div>`;if(missionTab==="completed"){let shown=completedMissionFilter==="archive"?archived:recent;return header("Missões","Abertas, concluídas recentes e histórico",`<button class="btn" data-act="newMission">＋ Nova missão</button>`)+tabs+`<div class="archiveHint"><div><b>✓ Conclusões organizadas automaticamente</b><span>Ao concluir, a missão sai de Abertas. Depois de 24 horas, ela deixa a lista recente e vai para o histórico — sem perder XP ou progresso.</span></div></div><div class="completedFilterBar"><button class="${completedMissionFilter==="recent"?"on":""}" data-completed-filter="recent">Últimas 24 horas <b>${recent.length}</b></button><button class="${completedMissionFilter==="archive"?"on":""}" data-completed-filter="archive">Histórico <b>${archived.length}</b></button></div><div class="list completedMissionList">${shown.length?shown.map(completedMissionCard).join(""):`<div class="card emptyMissionState"><b>${completedMissionFilter==="recent"?"Nenhuma conclusão nas últimas 24 horas":"O histórico ainda está vazio"}</b><span>${completedMissionFilter==="recent"?"As próximas missões concluídas aparecerão aqui por um dia.":"Conclusões com mais de 24 horas serão guardadas aqui."}</span></div>`}</div>`}return header("Missões","Missões do dia, plano inicial, desafios e Protocolos",`<div class="row missionHeadButtons"><button class="pill aiMainButton" data-act="aiCenter">✦ Central IA</button><button class="btn" data-act="newMission">＋ Nova missão</button></div>`)+tabs+`<div class="card aiMissionCard"><div><span class="kicker">COORDENADOR SMART // IA</span><h2>Planeje mais com o Gemini</h2><p class="sub">Crie missões, planeje uma meta, organize a semana ou faça uma revisão semanal. ${ai.apiKey?"A conexão já está configurada neste dispositivo.":"Configure sua chave do Gemini para ativar."}</p></div><div class="row aiMissionActions"><button class="btn" data-act="aiMissions">✨ Gerar Missões com IA</button><button class="pill" data-act="aiCenter">✦ Ver todas as ações</button><button class="pill" data-nav="settings">Configurar IA</button></div></div><div class="adaptiveInfo"><b>Smart Daily adaptativo</b><span>Ritmo atual: ${perf.mode==="leve"?"mais leve":perf.mode==="desafio"?"desafio maior":"equilibrado"}. O sistema ajusta esforço e tempo estimado usando seu desempenho recente.</span></div><div class="section"><div><h2>Smart Daily</h2><span class="sub">${qty(daily.length,"pendente hoje","pendentes hoje")} • geradas conforme sua situação atual</span></div></div><div class="list dailyMissionList">${daily.length?daily.map(missionCard).join(""):`<div class="card sub">Nenhuma missão Smart Daily pendente agora.</div>`}</div><div class="section"><h2>Plano e outras missões</h2><span class="sub">${active.length} ativa(s)</span></div><div class="list">${active.length?active.map(missionCard).join(""):`<div class="card sub">Você não tem outras missões ativas agora.</div>`}</div><div class="section"><h2>Protocolos</h2></div><div class="grid3">${[[7,"Adaptação"],[21,"Consolidação"],[30,"Consistência"],[90,"Transformação"]].map(x=>`<div class="card"><h2>${x[0]} dias</h2><p class="sub">${x[1]}</p><button class="pill" data-proto="${x[0]}">Criar</button></div>`).join("")}</div>`}
function projectPct(p){let target=Number(p.target||0),current=Number(p.current||0);if((p.type==="money"||p.type==="count")&&target>0)return Math.max(0,Math.min(100,current/target*100));return Math.max(0,Math.min(100,Number(p.progress||0)))}
function pctText(n){n=Math.round(Number(n||0)*10)/10;return Number.isInteger(n)?String(n):n.toFixed(1).replace(".",",")}
function projects(){return header("Projetos & Metas","Transforme objetivos grandes em metas claras, acompanhe o progresso e crie um plano de ação.",`<div class="row projectHeadButtons"><button class="pill" data-act="newPlan">✦ Criar plano</button><button class="btn" data-act="newProject">＋ Novo projeto</button></div>`)+`<div class="list">${D.projects.length?D.projects.map(p=>{let fm=p.type==="money",fc=p.type==="count",target=Number(p.target||0),current=Number(p.current||0),pct=projectPct(p),unit=esc(p.unit||"unidades"),detail="",last=p.updates?.[0];if(fm)detail=`<div class="moneyGrid"><div class="moneyBox"><small>Valor atual</small><b>${current.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}</b></div><div class="moneyBox"><small>Valor final</small><b>${target.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}</b></div></div><p class="xp">Faltam ${Math.max(0,target-current).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}</p>`;if(fc)detail=`<div class="moneyGrid"><div class="moneyBox"><small>Valor atual</small><b>${current.toLocaleString("pt-BR")} ${unit}</b></div><div class="moneyBox"><small>Meta final</small><b>${target.toLocaleString("pt-BR")} ${unit}</b></div></div><p class="xp">Faltam ${Math.max(0,target-current).toLocaleString("pt-BR")} ${unit}</p>`;let quick=fm?`<div class="projectQuickAdd"><span>Adicionar:</span><button class="quickValue" data-project-add="${p.id}:10">+ R$ 10</button><button class="quickValue" data-project-add="${p.id}:100">+ R$ 100</button><button class="quickValue" data-project-add="${p.id}:500">+ R$ 500</button><button class="quickValue custom" data-project-add-custom="${p.id}">Outro valor</button></div>`:fc?`<div class="projectQuickAdd"><span>Adicionar:</span><button class="quickValue" data-project-add="${p.id}:1">+1</button><button class="quickValue" data-project-add="${p.id}:5">+5</button><button class="quickValue" data-project-add="${p.id}:10">+10</button><button class="quickValue custom" data-project-add-custom="${p.id}">Outro valor</button></div>`:"";return `<div class="card projectCard"><div class="row between"><div><div class="kicker">${fm?"META FINANCEIRA":fc?"META NUMÉRICA":"PROJETO"}</div><h2>${esc(p.title)}</h2></div>${p.due?`<span class="badge">${esc(p.due.split("-").reverse().join("/"))}</span>`:""}</div><p class="sub">${esc(p.desc||"Sem descrição")}</p>${detail}<div class="label"><span>Progresso</span><b>${pctText(pct)}%</b></div><div class="bar"><i style="width:${pct}%"></i></div>${quick}${last?`<div class="projectLastUpdate">Última adição: <b>${fm?Number(last.amount).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}):`${Number(last.amount).toLocaleString("pt-BR")} ${unit}`}</b> • ${esc(last.date||"")}</div>`:""}<div class="projectActions">${fm?`<button class="pill" data-project-money="${p.id}">Definir total</button>`:fc?`<button class="pill" data-project-count="${p.id}">Definir total</button>`:`<button class="pill" data-project-progress="${p.id}:-10">−10%</button><button class="pill" data-project-progress="${p.id}:10">＋10%</button>`}<button class="pill" data-project-edit="${p.id}">Editar</button><button class="btn red" data-project-del="${p.id}">Excluir</button></div></div>`}).join(""):`<div class="card sub">Nenhum projeto cadastrado.</div>`}</div>`}
function buildPlanMissions(project,kind){let due=project.due||"",base=[];if(kind==="money")base=[["Defina o primeiro aporte","Escolha um valor realista para começar sua meta financeira.",55,15],["Faça um aporte na meta","Registre qualquer valor que avance sua meta.",70,10],["Revise seus gastos da semana","Procure uma despesa que pode ser reduzida sem comprometer o essencial.",65,20],["Confira o progresso financeiro","Veja quanto já foi acumulado e quanto ainda falta.",55,10],["Planeje o próximo aporte","Defina quando e quanto pretende adicionar novamente.",60,15]];else if(kind==="count")base=[["Avance uma unidade hoje",`Faça pelo menos +1 ${project.unit||"unidade"} na sua meta.`,60,15],["Registre seu progresso","Atualize o valor atual da meta para manter o acompanhamento correto.",50,5],["Proteja a sequência","Faça a menor ação possível para não deixar a meta parada.",60,15],["Revise o ritmo da meta","Compare o progresso atual com o prazo final.",55,10],["Planeje o próximo avanço","Defina o próximo passo concreto da meta.",55,10]];else base=[["Defina o próximo passo","Escolha uma ação pequena e objetiva para avançar o projeto.",55,10],["Execute um bloco de foco","Trabalhe no projeto sem distrações por um período curto.",70,25],["Atualize o progresso","Registre o que foi concluído e o próximo passo.",50,10],["Remova um obstáculo","Resolva uma pendência que está impedindo o projeto de avançar.",65,20],["Revise o prazo","Confira se o ritmo atual é suficiente para concluir a tempo.",50,10]];
 return base.map((x,i)=>({id:id(),title:x[0],desc:`${x[1]} • Plano: ${project.title}`,due:i===0?iso():due,xp:x[2],estimatedMinutes:x[3],done:false,expired:false,source:"project-plan",category:"Plano • "+project.title,projectId:project.id,createdAt:new Date().toISOString()}))}
function planModal(){modal(`<div class="mh"><div><h2>Criar um plano</h2><p class="sub">Crie uma meta e deixe o Smart Life preparar os primeiros passos.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>O que você quer alcançar?</label><input id="plTitle" class="field" placeholder="Ex.: 500 dias de ofensiva no Duolingo"><label>Tipo de plano</label><select id="plType" class="field"><option value="count">Meta numérica</option><option value="money">Meta financeira</option><option value="progress">Projeto por progresso</option></select><label>Descrição</label><textarea id="plDesc" class="field" placeholder="Explique brevemente sua meta"></textarea><label>Prazo</label><input id="plDue" class="field" type="date"><div id="plNumeric"><div class="profileEditGrid"><div><label>Meta final</label><input id="plTarget" class="field" type="number" min="0" step="any" placeholder="500"></div><div><label>Quanto já fez?</label><input id="plCurrent" class="field" type="number" min="0" step="any" value="0"></div></div><label>Unidade</label><input id="plUnit" class="field" value="dias" placeholder="dias, km, aulas..."></div><div id="plMoney" style="display:none"><div class="profileEditGrid"><div><label>Valor final</label><input id="plMoneyTarget" class="field" type="number" min="0" step="0.01" placeholder="5000"></div><div><label>Valor atual</label><input id="plMoneyCurrent" class="field" type="number" min="0" step="0.01" value="0"></div></div></div><div id="plProgress" style="display:none"><label>Progresso atual (%)</label><input id="plPct" class="field" type="number" min="0" max="100" value="0"></div><div class="planPreview"><b>O plano vai criar:</b><span>1 meta acompanhável + 5 missões iniciais ligadas a ela.</span></div><button class="btn" id="plSave" style="margin-top:14px">Criar plano</button></div>`);let sync=()=>{let t=plType.value;plNumeric.style.display=t==="count"?"block":"none";plMoney.style.display=t==="money"?"block":"none";plProgress.style.display=t==="progress"?"block":"none"};byId("cx").onclick=closeM;plType.onchange=sync;sync();plSave.onclick=()=>{let title=plTitle.value.trim(),type=plType.value;if(!title)return toast("Informe o objetivo do plano.","warn");let project={id:id(),title,desc:plDesc.value.trim(),type,due:plDue.value,progress:type==="progress"?Math.max(0,Math.min(100,Number(plPct.value)||0)):0,target:type==="count"?Math.max(0,Number(plTarget.value)||0):type==="money"?Math.max(0,Number(plMoneyTarget.value)||0):0,current:type==="count"?Math.max(0,Number(plCurrent.value)||0):type==="money"?Math.max(0,Number(plMoneyCurrent.value)||0):0,unit:type==="count"?(plUnit.value.trim()||"unidades"):"",updates:[],done:false,createdAt:new Date().toISOString()};if((type==="count"||type==="money")&&project.target<=0)return toast("Informe uma meta final maior que zero.","warn");project.done=type==="progress"?project.progress>=100:project.current>=project.target;D.projects.push(project);D.missions.push(...buildPlanMissions(project,type));evaluateTitles(true);save();closeM();nav="projects";render();toast("Meta criada com 5 missões iniciais para ajudar você a avançar.","success","Plano criado")}}
function projectModal(existing){let p=existing||{id:id(),title:"",desc:"",type:"progress",progress:0,target:0,current:0,unit:"dias",due:"",updates:[]};p.updates=Array.isArray(p.updates)?p.updates:[];modal(`<div class="mh"><div><h2>${existing?"Editar":"Novo"} projeto</h2><p class="sub">Use porcentagem, meta numérica ou meta de dinheiro.</p></div><button class="x" id="cx">×</button></div><div class="form" id="projectForm"><label>Nome</label><input id="pjTitle" class="field" value="${esc(p.title)}"><label>Tipo</label><select id="pjType" class="field"><option value="progress" ${p.type==="progress"||(!p.type)?"selected":""}>Progresso (%)</option><option value="count" ${p.type==="count"?"selected":""}>Meta numérica</option><option value="money" ${p.type==="money"?"selected":""}>Meta de dinheiro</option></select><label>Descrição</label><textarea id="pjDesc" class="field">${esc(p.desc||"")}</textarea><label>Prazo</label><input id="pjDue" type="date" class="field" value="${esc(p.due||"")}"><div id="pjProgressWrap"><label>Progresso (%)</label><input id="pjProgress" type="number" min="0" max="100" step="0.1" class="field" value="${Number(p.progress||0)}"></div><div id="pjCountWrap"><div class="profileEditGrid"><div><label>Meta final</label><input id="pjCountTarget" type="number" min="0" step="any" class="field" value="${p.type==='count'?Number(p.target||0):0}" placeholder="Ex.: 500"></div><div><label>Valor atual</label><input id="pjCountCurrent" type="number" min="0" step="any" class="field" value="${p.type==='count'?Number(p.current||0):0}" placeholder="Ex.: 479"></div></div><label>Unidade</label><input id="pjUnit" class="field" value="${esc(p.unit||'dias')}" placeholder="dias, aulas, km, livros..."><p class="sub">Ex.: meta 500 e atual 479 = 95,8% automaticamente.</p></div><div id="pjMoneyWrap"><div class="profileEditGrid"><div><label>Valor final</label><input id="pjTarget" type="number" min="0" step="0.01" class="field" value="${p.type==='money'?Number(p.target||0):0}"></div><div><label>Valor atual</label><input id="pjCurrent" type="number" min="0" step="0.01" class="field" value="${p.type==='money'?Number(p.current||0):0}"></div></div></div><button class="btn" id="pjSave" style="margin-top:16px">Salvar projeto</button></div>`);let sync=()=>{let t=pjType.value;pjMoneyWrap.style.display=t==="money"?"block":"none";pjCountWrap.style.display=t==="count"?"block":"none";pjProgressWrap.style.display=t==="progress"?"block":"none"};cx.onclick=closeM;pjType.onchange=sync;sync();pjSave.onclick=()=>{if(!pjTitle.value.trim())return toast("Informe o nome do projeto.","warn");let t=pjType.value,obj={...p,title:pjTitle.value.trim(),desc:pjDesc.value.trim(),type:t,due:pjDue.value,progress:Math.max(0,Math.min(100,+pjProgress.value||0)),target:t==="money"?Math.max(0,+pjTarget.value||0):t==="count"?Math.max(0,+pjCountTarget.value||0):0,current:t==="money"?Math.max(0,+pjCurrent.value||0):t==="count"?Math.max(0,+pjCountCurrent.value||0):0,unit:t==="count"?(pjUnit.value.trim()||"unidades"):""};if((t==="money"||t==="count")&&obj.target<=0)return toast("Informe uma meta final maior que zero.","warn");obj.done=t==="money"||t==="count"?obj.target>0&&obj.current>=obj.target:obj.progress>=100;let i=D.projects.findIndex(x=>x.id===obj.id);i>=0?D.projects[i]=obj:D.projects.push(obj);evaluateTitles(true);save();closeM();render();toast(t==="count"?`Progresso calculado: ${pctText(projectPct(obj))}%.`:"Projeto e progresso foram atualizados.","success","Projeto salvo")}}
function projectMoneyModal(p){let target=Number(p.target||0);modal(`<div class="mh"><div><div class="kicker">META FINANCEIRA</div><h2>Atualizar valor</h2><p class="sub">${esc(p.title)}</p></div><button class="x" id="cx">×</button></div><div class="moneyUpdateHero"><span>Objetivo final</span><b>${target.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}</b></div><div class="form"><label>Valor atual</label><div class="moneyInput"><span>R$</span><input id="pmValue" class="field" inputmode="decimal" value="${Number(p.current||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})}"></div><p class="sub">Informe quanto você já possui para esta meta.</p><div class="modalActions"><button class="pill" id="pmCancel">Cancelar</button><button class="btn" id="pmSave">Salvar valor</button></div></div>`);cx.onclick=closeM;pmCancel.onclick=closeM;setTimeout(()=>{pmValue.focus();pmValue.select()},0);pmSave.onclick=()=>{let raw=pmValue.value.trim().replace(/\./g,"").replace(",","."),n=Number(raw);if(!Number.isFinite(n)||n<0)return toast("Informe um valor válido.","warn");p.current=n;p.done=p.target>0&&p.current>=p.target;evaluateTitles(true);save();closeM();render();toast(`Valor atual: ${n.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}.`,"success","Meta atualizada")}}
function projectCountModal(p){let target=Number(p.target||0),unit=esc(p.unit||"unidades");modal(`<div class="mh"><div><div class="kicker">META NUMÉRICA</div><h2>Atualizar progresso</h2><p class="sub">${esc(p.title)}</p></div><button class="x" id="cx">×</button></div><div class="moneyUpdateHero"><span>Meta final</span><b>${target.toLocaleString("pt-BR")} ${unit}</b></div><div class="form"><label>Valor atual</label><input id="pcValue" class="field" inputmode="decimal" type="number" min="0" step="any" value="${Number(p.current||0)}"><p class="sub" id="pcPreview">Progresso: ${pctText(projectPct(p))}%</p><div class="modalActions"><button class="pill" id="pcCancel">Cancelar</button><button class="btn" id="pcSave">Salvar progresso</button></div></div>`);cx.onclick=closeM;pcCancel.onclick=closeM;pcValue.oninput=()=>{let n=Number(pcValue.value||0),pct=target>0?Math.max(0,Math.min(100,n/target*100)):0;pcPreview.textContent=`Progresso: ${pctText(pct)}%`};setTimeout(()=>{pcValue.focus();pcValue.select()},0);pcSave.onclick=()=>{let n=Number(pcValue.value);if(!Number.isFinite(n)||n<0)return toast("Informe um valor válido.","warn");p.current=n;p.done=p.target>0&&p.current>=p.target;evaluateTitles(true);save();closeM();render();toast(`Progresso: ${pctText(projectPct(p))}% (${n.toLocaleString("pt-BR")} de ${target.toLocaleString("pt-BR")} ${unit}).`,"success","Meta atualizada")}}
function addProjectValue(p,amount){amount=Number(amount);if(!p||!Number.isFinite(amount)||amount<=0)return toast("Informe um valor maior que zero.","warn");p.current=Number(p.current||0)+amount;p.updates=Array.isArray(p.updates)?p.updates:[];p.updates.unshift({id:id(),amount,date:new Date().toLocaleDateString("pt-BR"),time:new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})});p.updates=p.updates.slice(0,100);p.done=Number(p.target||0)>0&&p.current>=Number(p.target||0);hist("project_add",{project:p.title,amount,type:p.type});evaluateTitles(true);save();render();let msg=p.type==="money"?`${amount.toLocaleString("pt-BR",{style:"currency",currency:"BRL"})} adicionados. Total: ${Number(p.current).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}.`:`+${amount.toLocaleString("pt-BR")} ${p.unit||"unidades"}. Total: ${Number(p.current).toLocaleString("pt-BR")} de ${Number(p.target||0).toLocaleString("pt-BR")}.`;toast(msg,"success","Progresso adicionado")}
function projectAddModal(p){let money=p.type==="money",unit=esc(p.unit||"unidades");modal(`<div class="mh"><div><div class="kicker">${money?"META FINANCEIRA":"META NUMÉRICA"}</div><h2>Adicionar ao progresso</h2><p class="sub">${esc(p.title)}</p></div><button class="x" id="cx">×</button></div><div class="moneyUpdateHero"><span>Total atual</span><b>${money?Number(p.current||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}):`${Number(p.current||0).toLocaleString("pt-BR")} ${unit}`}</b></div><div class="form"><label>Quanto deseja adicionar?</label>${money?`<div class="moneyInput"><span>R$</span><input id="paValue" class="field" inputmode="decimal" placeholder="0,00"></div>`:`<input id="paValue" class="field" type="number" min="0" step="any" inputmode="decimal" placeholder="Ex.: 1">`}<p class="sub">O valor será somado ao total atual e a porcentagem será recalculada automaticamente.</p><div class="projectAddPresets">${(money?[10,100,500]:[1,5,10]).map(n=>`<button class="pill" type="button" data-pa-preset="${n}">+${money?` R$ ${n}`:n}</button>`).join("")}</div><div class="modalActions"><button class="pill" id="paCancel">Cancelar</button><button class="btn" id="paSave">Adicionar</button></div></div>`);cx.onclick=closeM;paCancel.onclick=closeM;document.querySelectorAll("[data-pa-preset]").forEach(b=>b.onclick=()=>{paValue.value=money?Number(b.dataset.paPreset).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2}):b.dataset.paPreset;paValue.focus()});setTimeout(()=>paValue.focus(),0);paSave.onclick=()=>{let raw=String(paValue.value||"").trim();if(money)raw=raw.replace(/\./g,"").replace(",",".");let n=Number(raw);if(!Number.isFinite(n)||n<=0)return toast("Informe um valor maior que zero.","warn");closeM();addProjectValue(p,n)}}
function organize(){let p=D.pages.find(x=>x.id===D.activePage)||D.pages[0];D.activePage=p?.id;return header("Organização","Seu espaço estilo Notion",`<button class="btn" data-act="newPage">＋ Página</button>`)+`<div class="notion"><div class="card pages">${D.pages.map(x=>`<button class="${x.id===p?.id?"on":""}" data-page="${x.id}">▤ ${esc(x.title)}</button>`).join("")}</div><div class="card editor">${p?`<input id="pt" class="field" value="${esc(p.title)}" style="font-size:24px;font-weight:900;border:0;padding-left:0"><div id="pe" contenteditable="true">${esc(p.content).replace(/\n/g,"<br>")}</div><div class="row"><button class="btn" data-savepage="${p.id}">Salvar</button><button class="btn red" data-delpage="${p.id}">Excluir</button></div>`:`<p class="sub">Crie uma página.</p>`}</div></div>`}
function profile(){let r=rank(),eq=D.titles.find(t=>t.equipped),x=levelCalc();return header("Perfil","Sua identidade e evolução dentro do sistema",`<div class="row profileHeaderActions"><button class="pill" data-nav="settings">⚙ Configurações</button><button class="pill" data-act="editProfile">✎ Editar perfil</button></div>`)+`<div class="profileHero card glow"><div class="profileHeroAvatar avatar">${avatarHTML()}</div><div class="profileHeroMain"><span class="kicker">JOGADOR • RANK ${r[0]}</span><h1>${esc(D.profile.name)}</h1><p class="sub">@${esc(D.profile.username)} • ${esc(r[1])}</p><div class="profileBadges"><span>🏆 ${esc(eq?.name||"Sem título")}</span><span>✦ Level ${D.level}</span><span>ϟ ${D.totalXP.toLocaleString("pt-BR")} XP</span></div><div class="label"><span>Próximo nível</span><b>${x.x}/${x.n} XP</b></div><div class="bar"><i style="width:${x.x/x.n*100}%"></i></div></div></div><div class="stats profileStats"><div class="stat">🔥 Melhor Streak<b>${D.bestStreak}</b><small>dias</small></div><div class="stat">✓ Conclusões<b>${D.history.filter(x=>x.type==="habit_done").length}</b><small>hábitos</small></div><div class="stat">⚑ Missões<b>${D.missions.filter(x=>x.done).length}</b><small>concluídas</small></div><div class="stat">◆ Projetos<b>${D.projects.filter(x=>x.done).length}</b><small>finalizados</small></div></div><div class="section"><h2>Perfil de Habilidades</h2><span class="sub">Seus Status de forma clara e comparável.</span></div>${skillProfile()}`}
function resetPlayerProgress(){
 let keepProfile={...D.profile},keepSettings={...D.settings},keepFinance=JSON.parse(JSON.stringify(D.finance||emptyFinance())),keepOnboarding=D.onboardingProfile,clean=fresh(false);
 clean.onboarded=true;clean.onboardingProfile=keepOnboarding;clean.finance=keepFinance;clean.profile={...clean.profile,...keepProfile};clean.settings={...clean.settings,...keepSettings};
 D=clean;if(Array.isArray(D.onboardingProfile?.answers))createOnboardingMissionPlan(D.onboardingProfile.answers);save();applyTheme();closeM();nav="missions";render();toast("Progresso zerado e um novo plano inicial foi criado com base nas suas respostas.","success","Personagem reiniciado")
}
function resetPlayerModal(){modal(`<div class="mh"><div><h2>Reiniciar personagem?</h2><p class="sub">Zera apenas o progresso do personagem e mantém sua identidade e preferências.</p></div><button class="x" id="cx">×</button></div><div class="dangerBox"><b>O que será zerado</b><p>XP, nível, atributos, sequência, títulos, hábitos, missões, projetos, histórico e registros das ferramentas.</p><p><b>Seu nome, foto, nome de usuário, tema e preferências serão mantidos.</b></p></div><div class="modalActions"><button class="pill" id="playerResetCancel">Cancelar</button><button class="btn red" id="playerResetConfirm">Reiniciar personagem</button></div>`);byId("playerResetCancel").onclick=closeM;byId("playerResetConfirm").onclick=resetPlayerProgress}

function financeOwnerId(){return Number(D.finance?.selectedOwnerId||0)}
function financeOwn(r,owner=financeOwnerId()){return Number(r?.owner_id)===Number(owner)}
function moneyBR(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}
function financeMonth(){return iso().slice(0,7)}
function financeMonthLabel(month){if(!/^\d{4}-\d{2}$/.test(String(month||"")))return month||"";let [y,m]=month.split("-").map(Number);return new Intl.DateTimeFormat("pt-BR",{month:"long",year:"numeric"}).format(new Date(y,m-1,1))}
function financeShiftMonth(month,delta){let [y,m]=String(month||financeMonth()).split("-").map(Number),d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}
function financeDateForMonthDay(month,day){let [y,m]=String(month).split("-").map(Number),last=new Date(y,m,0).getDate(),d=Math.max(1,Math.min(last,Number(day)||1));return `${y}-${String(m).padStart(2,"0")}-${String(d).padStart(2,"0")}`}
function financeRecordMonth(r,kind){let v=kind==="expense"?(r.list_month||r.billing_month||r.due_date||r.purchase_date):(r.expected_date||r.received_date);return String(v||"").slice(0,7)}
function financeCatName(id){return D.finance.categories.find(c=>Number(c.id)===Number(id))?.name||"Sem categoria"}
function financeCardName(id){return D.finance.cards.find(a=>Number(a.id)===Number(id))?.name||""}
function financeSummary(month=financeMonthSelected){let o=financeOwnerId(),inc=D.finance.incomes.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"income")===month),exp=D.finance.expenses.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"expense")===month),expected=inc.reduce((s,x)=>s+Number(x.amount_expected||0),0),received=inc.reduce((s,x)=>s+Number(x.amount_received||0),0),totalExp=exp.reduce((s,x)=>s+Number(x.amount||0),0),paid=exp.filter(x=>String(x.status)==="paid"||x.paid_date).reduce((s,x)=>s+Number(x.amount||0),0),pending=Math.max(0,totalExp-paid);return{inc,exp,expected,received,totalExp,paid,pending,balance:received-paid,commit:expected?Math.min(999,totalExp/expected*100):0}}
function financeMonthControls(){return `<div class="financeMonthControls"><button class="iconAction" data-fin-month-step="-1" title="Mês anterior">‹</button><input id="financeMonthInput" class="field financeMonthInput" type="month" value="${financeMonthSelected}"><button class="iconAction" data-fin-month-step="1" title="Próximo mês">›</button><button class="pill" data-fin-month-current>Hoje</button></div>`}
function financeTabs(){let tabs=[["dashboard","Visão geral"],["incomes","Receitas"],["expenses","Despesas"],["cards","Cartões"],["loans","Empréstimos"],["recurring","Recorrentes"],["planning","Planejamento"]];return `<div class="financeTabs">${tabs.map(t=>`<button class="${financeTab===t[0]?"on":""}" data-fin-tab="${t[0]}">${t[1]}</button>`).join("")}</div>`}
function financeRecurrenceActiveForMonth(r,month){let start=String(r.start_month||month).slice(0,7),end=String(r.end_month||"").slice(0,7);return Number(r.active)!==0&&month>=start&&(!end||month<=end)}
function ensureFinanceRecurringForMonth(month){let o=financeOwnerId(),added=0;D.finance.recurring_expenses.filter(x=>financeOwn(x,o)&&financeRecurrenceActiveForMonth(x,month)).forEach(r=>{if(D.finance.expenses.some(e=>Number(e.recurrence_id)===Number(r.id)&&financeRecordMonth(e,"expense")===month))return;let due=financeDateForMonthDay(month,r.due_day);D.finance.expenses.push({id:nextFinanceId(D.finance.expenses),owner_id:o,description:r.description,amount:Number(r.amount||0),purchase_date:due,due_date:due,paid_date:null,category_id:r.category_id??null,expense_type:"fixed",payment_method:r.payment_method||"pix",merchant:r.merchant||"",notes:"",status:"pending",account_id:r.account_id??null,card_id:null,attachment_path:null,recurrence_id:r.id,installment_group:null,installment_number:null,total_installments:null,billing_month:month,list_month:month,created_at:new Date().toISOString(),external_id:null});added++});D.finance.recurring_incomes.filter(x=>financeOwn(x,o)&&financeRecurrenceActiveForMonth(x,month)).forEach(r=>{if(D.finance.incomes.some(e=>Number(e.recurrence_id)===Number(r.id)&&financeRecordMonth(e,"income")===month))return;let date=financeDateForMonthDay(month,r.expected_day);D.finance.incomes.push({id:nextFinanceId(D.finance.incomes),owner_id:o,description:r.description,amount_expected:Number(r.amount||0),amount_received:0,expected_date:date,received_date:null,status:"pending",account_id:r.account_id??null,category_id:r.category_id??null,notes:r.notes||"",created_at:new Date().toISOString(),recurrence_id:r.id,external_id:null,attachment_path:null});added++});return added}
function finance(){let owner=financeOwnerId(),user=D.finance.users.find(u=>Number(u.id)===owner);let added=ensureFinanceRecurringForMonth(financeMonthSelected);if(added)try{localStorage.setItem(KEY,JSON.stringify(D))}catch{};let top=header("Finanças","Smart Finance integrado ao Smart Life",`<div class="row financeHeadActions"><button class="pill" data-fin-export>⇩ Exportar</button><button class="pill" data-fin-import>⇧ Importar</button></div>`)+`<div class="financeSource"><span>Dados importados do Smart Finance${user?` • ${esc(user.display_name||user.username)}`:""}</span><small>As contas bancárias continuam preservadas no backup para compatibilidade, mas foram removidas da interface do Smart Life para deixar o módulo mais simples.</small></div>`+`<div class="financeTopRow">${financeMonthControls()}<span class="financeMonthLabel">${esc(financeMonthLabel(financeMonthSelected))}</span></div>`+financeTabs();return top+(financeTab==="dashboard"?financeDashboard():financeTab==="incomes"?financeIncomes():financeTab==="expenses"?financeExpenses():financeTab==="cards"?financeCards():financeTab==="loans"?financeLoans():financeTab==="recurring"?financeRecurring():financePlanning())}
function financeDashboard(){let s=financeSummary(),o=financeOwnerId(),cards=D.finance.cards.filter(x=>financeOwn(x,o)&&Number(x.is_active)!==0),recent=[...s.exp].filter(x=>String(x.status)!=="paid"&&!x.paid_date).sort((a,b)=>String(a.due_date||"").localeCompare(String(b.due_date||""))).slice(0,6),rec=D.finance.recurring_expenses.filter(x=>financeOwn(x,o)&&Number(x.active)!==0).length+D.finance.recurring_incomes.filter(x=>financeOwn(x,o)&&Number(x.active)!==0).length,budgets=D.finance.budgets.filter(x=>financeOwn(x,o)&&String(x.month)===financeMonthSelected).length;return `<div class="financeMetrics"><div class="financeMetric"><span>Recebido no mês</span><b class="positive">${moneyBR(s.received)}</b><small>Previsto: ${moneyBR(s.expected)}</small></div><div class="financeMetric"><span>Despesas do mês</span><b>${moneyBR(s.totalExp)}</b><small>Pago: ${moneyBR(s.paid)}</small></div><div class="financeMetric"><span>Falta pagar</span><b class="warnText">${moneyBR(s.pending)}</b><small>${s.exp.filter(x=>String(x.status)!=="paid"&&!x.paid_date).length} pendência(s)</small></div><div class="financeMetric"><span>Saldo realizado</span><b class="${s.balance>=0?"positive":"negative"}">${moneyBR(s.balance)}</b><small>${s.commit.toLocaleString("pt-BR",{maximumFractionDigits:1})}% da renda prevista comprometida</small></div></div><div class="grid2 financeGrid"><div class="card"><div class="sectionMini"><h2>Próximas despesas</h2><button class="link" data-fin-tab="expenses">Ver despesas</button></div><div class="list">${recent.length?recent.map(e=>`<div class="financeLine"><div><b>${esc(e.description)}</b><small>${esc(financeCatName(e.category_id))} • ${String(e.due_date||"").split("-").reverse().join("/")}</small></div><strong>${moneyBR(e.amount)}</strong></div>`).join(""):`<p class="sub">Nenhuma despesa pendente neste mês.</p>`}</div></div><div class="card"><div class="sectionMini"><h2>Resumo do módulo</h2></div><div class="financeMiniGrid"><div><span>Cartões ativos</span><b>${cards.length}</b></div><div><span>Empréstimos</span><b>${D.finance.loans.filter(x=>financeOwn(x,o)&&Number(x.active)!==0).length}</b></div><div><span>Recorrências ativas</span><b>${rec}</b></div><div><span>Orçamentos no mês</span><b>${budgets}</b></div></div></div></div>`}
function financeDueState(x){if(String(x.status)==="paid"||x.paid_date)return["paid","Paga"];let today=iso(),due=String(x.due_date||"").slice(0,10);if(due&&due<today)return["overdue","Vencida"];let d=daysUntil(due);if(d!==null&&d>=0&&d<=3)return["soon",d===0?"Vence hoje":`Vence em ${d}d`];return["pending","Pendente"]}
function financeIncomes(){let o=financeOwnerId(),rows=D.finance.incomes.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"income")===financeMonthSelected).sort((a,b)=>String(a.expected_date||"").localeCompare(String(b.expected_date||"")));let cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind==="income");return `<div class="financeToolbar"><div><h2>Receitas</h2><p class="sub">Somente ${esc(financeMonthLabel(financeMonthSelected))}.</p></div><button class="btn" data-fin-new="income">＋ Nova receita</button></div><div class="financeFilters"><input id="finIncomeSearch" class="field" placeholder="Buscar receita..."><select id="finIncomeStatus" class="field"><option value="all">Todos os status</option><option value="pending">Pendentes</option><option value="received">Recebidas</option></select><select id="finIncomeCategory" class="field"><option value="all">Todas as categorias</option>${cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select><span class="financeCount">${rows.length} lançamento(s)</span></div><div class="financeTable" id="finIncomeRows">${rows.length?rows.map(x=>`<div class="financeRow financeFilterRow" data-fin-search="${esc(`${x.description} ${x.notes||""}`.toLocaleLowerCase("pt-BR"))}" data-fin-status="${esc(String(x.status))}" data-fin-category="${x.category_id||""}"><div><b>${esc(x.description)}</b><small>${String(x.expected_date||"").split("-").reverse().join("/")}${x.recurrence_id?` • ↻ Recorrente`:""}</small></div><div class="financeAmounts"><b class="positive">${moneyBR(x.amount_received||x.amount_expected)}</b><span class="status ${String(x.status)}">${String(x.status)==="received"?"Recebida":"Pendente"}</span></div><button class="iconAction" data-fin-edit="income:${x.id}" title="Editar">✎</button><button class="iconAction danger" data-fin-del="income:${x.id}" title="Excluir">×</button></div>`).join(""):`<div class="card sub">Nenhuma receita neste mês.</div>`}</div><div id="finIncomeEmpty" class="card sub financeFilteredEmpty" hidden>Nenhuma receita corresponde aos filtros.</div>`}
function financeExpenses(){let o=financeOwnerId(),rows=D.finance.expenses.filter(x=>financeOwn(x,o)&&financeRecordMonth(x,"expense")===financeMonthSelected).sort((a,b)=>{let ap=String(a.status)==="paid"?1:0,bp=String(b.status)==="paid"?1:0;return ap-bp||String(a.due_date||"").localeCompare(String(b.due_date||""))}),cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind==="expense");return `<div class="financeToolbar"><div><h2>Despesas</h2><p class="sub">Agora organizadas por mês, com pendentes primeiro.</p></div><button class="btn" data-fin-new="expense">＋ Nova despesa</button></div><div class="financeFilters"><input id="finExpenseSearch" class="field" placeholder="Buscar despesa..."><select id="finExpenseStatus" class="field"><option value="all">Todos os status</option><option value="pending">Pendentes</option><option value="paid">Pagas</option><option value="overdue">Vencidas</option></select><select id="finExpenseCategory" class="field"><option value="all">Todas as categorias</option>${cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select><span class="financeCount">${rows.length} lançamento(s)</span></div><div class="financeTable" id="finExpenseRows">${rows.length?rows.map(x=>{let [state,label]=financeDueState(x),search=`${x.description} ${x.merchant||""} ${financeCatName(x.category_id)}`.toLocaleLowerCase("pt-BR");return`<div class="financeRow financeFilterRow ${state}" data-fin-search="${esc(search)}" data-fin-status="${state}" data-fin-category="${x.category_id||""}"><div><b>${esc(x.description)}</b><small>${esc(financeCatName(x.category_id))} • venc. ${String(x.due_date||"").split("-").reverse().join("/")}${x.card_id?` • ${esc(financeCardName(x.card_id))}`:""}${x.recurrence_id?` • ↻ Recorrente`:""}</small></div><div class="financeAmounts"><b>${moneyBR(x.amount)}</b><span class="status ${state}">${label}</span></div><button class="iconAction" data-fin-toggle-paid="${x.id}" title="${String(x.status)==="paid"?"Reabrir":"Marcar como paga"}">${String(x.status)==="paid"?"↶":"✓"}</button><button class="iconAction" data-fin-edit="expense:${x.id}" title="Editar">✎</button><button class="iconAction danger" data-fin-del="expense:${x.id}" title="Excluir">×</button></div>`}).join(""):`<div class="card sub">Nenhuma despesa neste mês.</div>`}</div><div id="finExpenseEmpty" class="card sub financeFilteredEmpty" hidden>Nenhuma despesa corresponde aos filtros.</div>`}
function financeCards(){let o=financeOwnerId(),rows=D.finance.cards.filter(x=>financeOwn(x,o));return `<div class="financeToolbar"><div><h2>Cartões</h2><p class="sub">Fatura calculada pelo mês selecionado.</p></div><button class="btn" data-fin-new="card">＋ Novo cartão</button></div><div class="grid2">${rows.map(c=>{let items=D.finance.expenses.filter(e=>financeOwn(e,o)&&Number(e.card_id)===Number(c.id)&&financeRecordMonth(e,"expense")===financeMonthSelected),total=items.reduce((s,e)=>s+Number(e.amount||0),0),paid=items.filter(e=>String(e.status)==="paid"||e.paid_date).reduce((s,e)=>s+Number(e.amount||0),0);return`<div class="card financeCard" style="--card-accent:${esc(c.color||"var(--green)")}"><span class="kicker">${esc(c.brand||"Cartão")}</span><h2>${esc(c.name)}</h2><p class="sub">${esc(c.bank||"")}</p><div class="financeCardInfo"><span>Limite <b>${moneyBR(c.credit_limit)}</b></span><span>Fatura <b>${moneyBR(total)}</b></span><span>Em aberto <b>${moneyBR(Math.max(0,total-paid))}</b></span></div><div class="projectActions"><button class="pill" data-fin-invoice="${c.id}">Ver fatura</button><button class="pill" data-fin-edit="card:${c.id}">Editar</button></div></div>`}).join("")||`<div class="card sub">Nenhum cartão cadastrado.</div>`}</div>`}
function financeCardInvoice(cardId){let o=financeOwnerId(),card=D.finance.cards.find(c=>financeOwn(c,o)&&Number(c.id)===Number(cardId));if(!card)return;let items=D.finance.expenses.filter(e=>financeOwn(e,o)&&Number(e.card_id)===Number(cardId)&&financeRecordMonth(e,"expense")===financeMonthSelected).sort((a,b)=>String(a.due_date||"").localeCompare(String(b.due_date||""))),total=items.reduce((s,e)=>s+Number(e.amount||0),0),paid=items.filter(e=>String(e.status)==="paid"||e.paid_date).reduce((s,e)=>s+Number(e.amount||0),0);modal(`<div class="mh"><div><h2>Fatura ${esc(card.name)}</h2><p class="sub">${esc(financeMonthLabel(financeMonthSelected))} • ${items.length} lançamento(s)</p></div><button class="x" id="cx">×</button></div><div class="financeInvoiceSummary"><div><span>Total</span><b>${moneyBR(total)}</b></div><div><span>Pago</span><b class="positive">${moneyBR(paid)}</b></div><div><span>Em aberto</span><b class="warnText">${moneyBR(Math.max(0,total-paid))}</b></div></div><div class="list financeInvoiceList">${items.length?items.map(e=>`<div class="financeLine"><div><b>${esc(e.description)}</b><small>${esc(financeCatName(e.category_id))} • ${String(e.due_date||"").split("-").reverse().join("/")}</small></div><strong>${moneyBR(e.amount)}</strong></div>`).join(""):`<p class="sub">Nenhum lançamento nesta fatura.</p>`}</div><div class="modalActions"><button class="pill" data-close>Fechar</button></div>`)}
function financeLoanState(inst){if(String(inst.status)==="paid"||inst.paid_date)return["paid","Paga"];let due=String(inst.due_date||"").slice(0,10);if(due&&due<iso())return["overdue","Vencida"];let d=daysUntil(due);if(d===0)return["soon","Vence hoje"];if(d!==null&&d>0&&d<=5)return["soon",`Vence em ${d}d`];return["pending","Pendente"]}
function financeLoans(){let o=financeOwnerId(),rows=D.finance.loans.filter(x=>financeOwn(x,o));return `<div class="financeToolbar"><div><h2>Empréstimos</h2><p class="sub">Acompanhe saldo devedor, parcelas pagas e próximos vencimentos.</p></div></div><div class="grid2">${rows.map(l=>{let inst=D.finance.loan_installments.filter(i=>Number(i.loan_id)===Number(l.id)&&financeOwn(i,o)).sort((a,b)=>Number(a.installment_number||0)-Number(b.installment_number||0)||String(a.due_date||"").localeCompare(String(b.due_date||""))),paidInst=inst.filter(i=>String(i.status)==="paid"||i.paid_date),pendingInst=inst.filter(i=>String(i.status)!=="paid"&&!i.paid_date),paid=paidInst.length,totalCount=inst.length||Number(l.installment_count||0),paidValue=paidInst.reduce((s,i)=>s+Number(i.amount||0),0),remaining=pendingInst.reduce((s,i)=>s+Number(i.amount||0),0),scheduleTotal=inst.length?inst.reduce((s,i)=>s+Number(i.amount||0),0):Number(l.total_amount||0),next=[...pendingInst].sort((a,b)=>String(a.due_date||"").localeCompare(String(b.due_date||"")))[0],overdue=pendingInst.filter(i=>String(i.due_date||"").slice(0,10)<iso()).length,pct=scheduleTotal?Math.min(100,paidValue/scheduleTotal*100):(totalCount?paid/totalCount*100:0),last=inst[inst.length-1];return`<div class="card financeLoanCard"><div class="row between"><div><span class="kicker">EMPRÉSTIMO</span><h2>${esc(l.creditor)}</h2></div>${overdue?`<span class="status overdue">${overdue} atrasada(s)</span>`:`<span class="status ${remaining>0?"pending":"paid"}">${remaining>0?"Em andamento":"Quitado"}</span>`}</div><div class="loanNumbers"><div><span>Contratado</span><b>${moneyBR(l.principal_amount||l.total_amount)}</b></div><div><span>Total parcelado</span><b>${moneyBR(scheduleTotal)}</b></div><div><span>Já pago</span><b class="positive">${moneyBR(paidValue)}</b></div><div><span>Falta pagar</span><b class="warnText">${moneyBR(remaining)}</b></div></div><div class="label"><span>${paid}/${totalCount} parcelas pagas</span><b>${pct.toLocaleString("pt-BR",{maximumFractionDigits:1})}%</b></div><div class="bar"><i style="width:${pct}%"></i></div><div class="loanFooter"><span>Parcela padrão: <b>${moneyBR(l.installment_amount)}</b></span>${next?`<span>Próxima: <b>${String(next.due_date||"").split("-").reverse().join("/")}</b></span>`:""}${last?`<span>Última prevista: <b>${String(last.due_date||"").split("-").reverse().join("/")}</b></span>`:""}</div><div class="projectActions"><button class="btn" data-fin-loan-view="${l.id}">Ver todas as parcelas</button></div></div>`}).join("")||`<div class="card sub">Nenhum empréstimo cadastrado.</div>`}</div>`}
function financeLoanInstallmentsModal(loanId){let o=financeOwnerId(),loan=D.finance.loans.find(l=>financeOwn(l,o)&&Number(l.id)===Number(loanId));if(!loan)return;let inst=D.finance.loan_installments.filter(i=>financeOwn(i,o)&&Number(i.loan_id)===Number(loanId)).sort((a,b)=>Number(a.installment_number||0)-Number(b.installment_number||0)||String(a.due_date||"").localeCompare(String(b.due_date||""))),paid=inst.filter(i=>String(i.status)==="paid"||i.paid_date),pending=inst.filter(i=>String(i.status)!=="paid"&&!i.paid_date),paidValue=paid.reduce((s,i)=>s+Number(i.amount||0),0),remaining=pending.reduce((s,i)=>s+Number(i.amount||0),0),total=inst.reduce((s,i)=>s+Number(i.amount||0),0);modal(`<div class="mh"><div><h2>Parcelas • ${esc(loan.creditor)}</h2><p class="sub">${paid.length}/${inst.length||loan.installment_count} pagas • falta ${moneyBR(remaining)}</p></div><button class="x" id="cx">×</button></div><div class="financeInvoiceSummary loanSummary"><div><span>Total parcelado</span><b>${moneyBR(total||loan.total_amount)}</b></div><div><span>Pago</span><b class="positive">${moneyBR(paidValue)}</b></div><div><span>Falta pagar</span><b class="warnText">${moneyBR(remaining)}</b></div></div><div class="loanFilterBar"><button class="pill on" data-loan-filter="all">Todas (${inst.length})</button><button class="pill" data-loan-filter="pending">Pendentes (${pending.length})</button><button class="pill" data-loan-filter="paid">Pagas (${paid.length})</button></div><div class="loanInstallmentList" id="loanInstallmentList">${inst.length?inst.map(i=>{let [state,label]=financeLoanState(i);return`<div class="loanInstallment ${state}" data-loan-state="${state}"><div class="loanInstallmentNumber">${Number(i.installment_number||0)}ª</div><div class="grow"><b>${moneyBR(i.amount)}</b><small>Vencimento ${String(i.due_date||"").split("-").reverse().join("/")}${i.paid_date?` • paga em ${String(i.paid_date).split("-").reverse().join("/")}`:""}</small></div><span class="status ${state}">${label}</span><button class="pill" data-fin-loan-toggle="${i.id}">${state==="paid"?"Reabrir":"Marcar paga"}</button></div>`}).join(""):`<p class="sub">Nenhuma parcela cadastrada para este empréstimo.</p>`}</div><div class="modalActions"><button class="pill" data-close>Fechar</button></div>`);document.querySelectorAll("[data-loan-filter]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-loan-filter]").forEach(x=>x.classList.toggle("on",x===b));let f=b.dataset.loanFilter;byId("loanInstallmentList")?.querySelectorAll(".loanInstallment").forEach(row=>row.hidden=f!=="all"&&(f==="paid"?row.dataset.loanState!=="paid":row.dataset.loanState==="paid"))});document.querySelectorAll("[data-fin-loan-toggle]").forEach(b=>b.onclick=()=>financeLoanToggleInstallment(Number(b.dataset.finLoanToggle),loanId))}
function financeLoanToggleInstallment(installmentId,loanId){let i=D.finance.loan_installments.find(x=>Number(x.id)===Number(installmentId));if(!i)return;let paid=String(i.status)==="paid"||!!i.paid_date;i.status=paid?"pending":"paid";i.paid_date=paid?null:iso();save();toast(paid?"Parcela reaberta.":"Parcela marcada como paga.","success","Empréstimo atualizado");financeLoanInstallmentsModal(loanId)}
function financeRecurring(){let o=financeOwnerId(),ex=D.finance.recurring_expenses.filter(x=>financeOwn(x,o)).sort((a,b)=>Number(b.active)-Number(a.active)||String(a.description).localeCompare(String(b.description),"pt-BR")),inc=D.finance.recurring_incomes.filter(x=>financeOwn(x,o)).sort((a,b)=>Number(b.active)-Number(a.active)||String(a.description).localeCompare(String(b.description),"pt-BR")),activeEx=ex.filter(x=>Number(x.active)!==0&&financeRecurrenceActiveForMonth(x,financeMonthSelected)),activeInc=inc.filter(x=>Number(x.active)!==0&&financeRecurrenceActiveForMonth(x,financeMonthSelected)),monthlyEx=activeEx.reduce((s,x)=>s+Number(x.amount||0),0),monthlyInc=activeInc.reduce((s,x)=>s+Number(x.amount||0),0);return `<div class="financeRecurringHeader"><div><h2>Recorrentes</h2><p class="sub">Controle regras mensais sem misturar todos os lançamentos na mesma tela.</p></div><div class="row"><button class="pill" data-fin-rec-new="expense">＋ Despesa recorrente</button><button class="pill" data-fin-rec-new="income">＋ Receita recorrente</button></div></div><div class="recurringSummary"><div><span>Despesas ativas no mês</span><b class="warnText">${moneyBR(monthlyEx)}</b><small>${activeEx.length} regra(s)</small></div><div><span>Receitas ativas no mês</span><b class="positive">${moneyBR(monthlyInc)}</b><small>${activeInc.length} regra(s)</small></div><div><span>Impacto recorrente</span><b class="${monthlyInc-monthlyEx>=0?"positive":"negative"}">${moneyBR(monthlyInc-monthlyEx)}</b><small>${esc(financeMonthLabel(financeMonthSelected))}</small></div></div><div class="grid2"><div class="card"><div class="sectionMini"><h2>Despesas recorrentes</h2><span class="financeCount">${ex.length}</span></div><div class="list">${ex.map(x=>`<div class="financeRecurringItem ${Number(x.active)===0?"inactive":""}"><div class="grow"><b>${esc(x.description)}</b><small>Dia ${x.due_day} • ${moneyBR(x.amount)} • ${esc(financeCatName(x.category_id))}</small><span class="recurrenceState">${Number(x.active)!==0?"Ativa":"Pausada"} • desde ${esc(String(x.start_month||"").slice(0,7)||"sem início")}${x.end_month?` • até ${esc(x.end_month)}`:" • sem data final"}</span></div><button class="pill" data-fin-rec-edit="expense:${x.id}">Editar</button><button class="iconAction" data-fin-rec-toggle="expense:${x.id}" title="${Number(x.active)!==0?"Pausar":"Ativar"}">${Number(x.active)!==0?"Ⅱ":"▶"}</button><button class="iconAction danger" data-fin-rec-del="expense:${x.id}" title="Excluir recorrência">×</button></div>`).join("")||`<p class="sub">Nenhuma.</p>`}</div></div><div class="card"><div class="sectionMini"><h2>Receitas recorrentes</h2><span class="financeCount">${inc.length}</span></div><div class="list">${inc.map(x=>`<div class="financeRecurringItem ${Number(x.active)===0?"inactive":""}"><div class="grow"><b>${esc(x.description)}</b><small>Dia ${x.expected_day} • ${moneyBR(x.amount)} • ${esc(financeCatName(x.category_id))}</small><span class="recurrenceState">${Number(x.active)!==0?"Ativa":"Pausada"} • desde ${esc(String(x.start_month||"").slice(0,7)||"sem início")}${x.end_month?` • até ${esc(x.end_month)}`:" • sem data final"}</span></div><button class="pill" data-fin-rec-edit="income:${x.id}">Editar</button><button class="iconAction" data-fin-rec-toggle="income:${x.id}" title="${Number(x.active)!==0?"Pausar":"Ativar"}">${Number(x.active)!==0?"Ⅱ":"▶"}</button><button class="iconAction danger" data-fin-rec-del="income:${x.id}" title="Excluir recorrência">×</button></div>`).join("")||`<p class="sub">Nenhuma.</p>`}</div></div></div>`}
function financeRecurringModal(kind,obj){let o=financeOwnerId(),isExpense=kind==="expense",arr=isExpense?D.finance.recurring_expenses:D.finance.recurring_incomes,cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind===(isExpense?"expense":"income")),x=obj||{id:nextFinanceId(arr),owner_id:o,description:"",amount:0,[isExpense?"due_day":"expected_day"]:10,category_id:null,start_month:financeMonthSelected,end_month:null,active:1};modal(`<div class="mh"><div><h2>${obj?"Editar":"Nova"} ${isExpense?"despesa":"receita"} recorrente</h2><p class="sub">A regra será usada nos meses futuros sem encher a tela atual.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Descrição</label><input id="frDesc" class="field" value="${esc(x.description||"")}"><label>Valor</label><input id="frAmount" class="field" type="number" step="0.01" min="0" value="${Number(x.amount||0)}"><div class="formGrid2"><div><label>Dia do mês</label><input id="frDay" class="field" type="number" min="1" max="31" value="${Number(isExpense?x.due_day:x.expected_day)||10}"></div><div><label>Categoria</label><select id="frCat" class="field"><option value="">Sem categoria</option>${cats.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(x.category_id)?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div></div><div class="formGrid2"><div><label>Começa em</label><input id="frStart" class="field" type="month" value="${String(x.start_month||financeMonthSelected).slice(0,7)}"></div><div><label>Final opcional</label><input id="frEnd" class="field" type="month" value="${String(x.end_month||"").slice(0,7)}"></div></div>${isExpense?`<label>Estabelecimento</label><input id="frExtra" class="field" value="${esc(x.merchant||"")}" placeholder="Opcional">`:`<label>Observação</label><input id="frExtra" class="field" value="${esc(x.notes||"")}" placeholder="Opcional">`}<label class="toggle-line"><input id="frActive" type="checkbox" ${Number(x.active)!==0?"checked":""}> Recorrência ativa</label><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="frSave">Salvar recorrência</button></div></div>`);byId("frSave").onclick=()=>{let y={...x,description:byId("frDesc").value.trim(),amount:Number(byId("frAmount").value||0),category_id:Number(byId("frCat").value)||null,start_month:byId("frStart").value||financeMonthSelected,end_month:byId("frEnd").value||null,active:byId("frActive").checked?1:0};y[isExpense?"due_day":"expected_day"]=Math.max(1,Math.min(31,Number(byId("frDay").value)||10));if(isExpense){y.merchant=byId("frExtra").value.trim();y.payment_method=y.payment_method||"pix"}else y.notes=byId("frExtra").value.trim();if(!y.description||y.amount<=0)return toast("Informe descrição e valor da recorrência.","warn","Dados incompletos");let i=arr.findIndex(v=>Number(v.id)===Number(y.id));i>=0?arr[i]=y:arr.push(y);let from=financeMonthSelected;if(isExpense){D.finance.expenses.forEach(e=>{if(Number(e.recurrence_id)!==Number(y.id)||financeRecordMonth(e,"expense")<from||String(e.status)==="paid"||e.paid_date)return;let m=financeRecordMonth(e,"expense");e.description=y.description;e.amount=y.amount;e.category_id=y.category_id;e.merchant=y.merchant||"";e.due_date=financeDateForMonthDay(m,y.due_day);e.purchase_date=e.purchase_date||e.due_date})}else{D.finance.incomes.forEach(e=>{if(Number(e.recurrence_id)!==Number(y.id)||financeRecordMonth(e,"income")<from||String(e.status)==="received"||e.received_date)return;let m=financeRecordMonth(e,"income");e.description=y.description;e.amount_expected=y.amount;e.category_id=y.category_id;e.notes=y.notes||"";e.expected_date=financeDateForMonthDay(m,y.expected_day)})}if(y.active)ensureFinanceRecurringForMonth(financeMonthSelected);save();closeM();render();toast("Regra recorrente atualizada. Os próximos lançamentos usarão os novos dados.","success","Recorrência salva")}}
function financeRecurringToggle(kind,id){let arr=kind==="expense"?D.finance.recurring_expenses:D.finance.recurring_incomes,x=arr.find(v=>Number(v.id)===Number(id));if(!x)return;x.active=Number(x.active)===0?1:0;if(x.active)ensureFinanceRecurringForMonth(financeMonthSelected);save();render();toast(x.active?"Recorrência ativada.":"Recorrência pausada.","info","Recorrentes")}
function financeRecurringDeleteModal(kind,id){let isExpense=kind==="expense",arr=isExpense?D.finance.recurring_expenses:D.finance.recurring_incomes,x=arr.find(v=>Number(v.id)===Number(id));if(!x)return;modal(`<div class="mh"><div><h2>Excluir recorrência?</h2><p class="sub">${esc(x.description)} • ${moneyBR(x.amount)}</p></div><button class="x" id="cx">×</button></div><div class="dangerBox"><b>Escolha o que fazer com os lançamentos já gerados</b><p>Você pode apagar apenas a regra recorrente e manter os lançamentos existentes, ou também remover os lançamentos futuros ainda pendentes.</p></div><div class="recurringDeleteOptions"><button class="pill" id="recKeep">Excluir regra e manter lançamentos</button><button class="btn red" id="recFuture">Excluir regra + futuros pendentes</button></div><div class="modalActions"><button class="pill" data-close>Cancelar</button></div>`);let removeRule=()=>{if(isExpense)D.finance.recurring_expenses=D.finance.recurring_expenses.filter(v=>Number(v.id)!==Number(id));else D.finance.recurring_incomes=D.finance.recurring_incomes.filter(v=>Number(v.id)!==Number(id))};byId("recKeep").onclick=()=>{removeRule();save();closeM();render();toast("A regra foi excluída; lançamentos existentes foram mantidos.","info","Recorrência excluída")};byId("recFuture").onclick=()=>{let month=financeMonthSelected;if(isExpense)D.finance.expenses=D.finance.expenses.filter(e=>!(Number(e.recurrence_id)===Number(id)&&financeRecordMonth(e,"expense")>=month&&String(e.status)!=="paid"&&!e.paid_date));else D.finance.incomes=D.finance.incomes.filter(e=>!(Number(e.recurrence_id)===Number(id)&&financeRecordMonth(e,"income")>=month&&String(e.status)!=="received"&&!e.received_date));removeRule();save();closeM();render();toast("Regra e lançamentos futuros pendentes foram removidos.","info","Recorrência excluída")}}

function financePlanning(){let o=financeOwnerId(),months=[0,1,2].map(n=>financeShiftMonth(financeMonthSelected,n)),cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind==="expense"),budgets=D.finance.budgets.filter(x=>financeOwn(x,o)&&String(x.month)===financeMonthSelected);return `<div class="financeToolbar"><div><h2>Planejamento</h2><p class="sub">Previsão dos próximos meses e orçamento por categoria.</p></div><button class="btn" data-fin-budget-new>＋ Novo orçamento</button></div><div class="financeForecast">${months.map(m=>{ensureFinanceRecurringForMonth(m);let s=financeSummary(m),inst=D.finance.loan_installments.filter(i=>financeOwn(i,o)&&String(i.due_date||"").slice(0,7)===m&&String(i.status)!=="paid").reduce((a,i)=>a+Number(i.amount||0),0);return`<div class="card forecastCard"><b>${esc(financeMonthLabel(m))}</b><span>Receitas <strong class="positive">${moneyBR(s.expected)}</strong></span><span>Despesas <strong>${moneyBR(s.totalExp)}</strong></span><span>Parcelas <strong>${moneyBR(inst)}</strong></span><span>Saldo previsto <strong class="${s.expected-s.totalExp-inst>=0?"positive":"negative"}">${moneyBR(s.expected-s.totalExp-inst)}</strong></span></div>`}).join("")}</div><div class="card" style="margin-top:14px"><div class="sectionMini"><div><h2>Orçamento por categoria</h2><p class="sub">${esc(financeMonthLabel(financeMonthSelected))}</p></div></div><div class="budgetList">${budgets.length?budgets.map(b=>{let spent=D.finance.expenses.filter(e=>financeOwn(e,o)&&financeRecordMonth(e,"expense")===financeMonthSelected&&Number(e.category_id)===Number(b.category_id)).reduce((s,e)=>s+Number(e.amount||0),0),pct=Number(b.limit_amount)?spent/Number(b.limit_amount)*100:0;return`<div class="budgetRow"><div class="grow"><b>${esc(financeCatName(b.category_id))}</b><small>${moneyBR(spent)} de ${moneyBR(b.limit_amount)}</small><div class="bar"><i style="width:${Math.min(100,pct)}%"></i></div></div><strong class="${pct>100?"negative":""}">${pct.toFixed(0)}%</strong><button class="iconAction danger" data-fin-budget-del="${b.id}" title="Remover">×</button></div>`}).join(""):`<p class="sub">Nenhum orçamento definido para este mês.</p>`}</div></div>`}
function financeBudgetModal(){let o=financeOwnerId(),cats=D.finance.categories.filter(c=>financeOwn(c,o)&&c.kind==="expense");modal(`<div class="mh"><div><h2>Novo orçamento</h2><p class="sub">Defina um limite por categoria para ${esc(financeMonthLabel(financeMonthSelected))}.</p></div><button class="x" id="cx">×</button></div><div class="form"><label>Categoria</label><select id="fbCat" class="field"><option value="">Selecione</option>${cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select><label>Limite mensal</label><input id="fbLimit" class="field" type="number" min="0" step="0.01"><div class="modalActions"><button class="pill" data-close>Cancelar</button><button class="btn" id="fbSave">Salvar orçamento</button></div></div>`);byId("fbSave").onclick=()=>{let category_id=Number(byId("fbCat").value),limit_amount=Number(byId("fbLimit").value||0);if(!category_id||limit_amount<=0)return toast("Selecione uma categoria e informe o limite.","warn");let old=D.finance.budgets.find(b=>financeOwn(b,o)&&String(b.month)===financeMonthSelected&&Number(b.category_id)===category_id);if(old)old.limit_amount=limit_amount;else D.finance.budgets.push({id:nextFinanceId(D.finance.budgets),owner_id:o,month:financeMonthSelected,category_id,limit_amount,created_at:new Date().toISOString()});save();closeM();render();toast("Orçamento salvo para o mês.","success","Planejamento atualizado")}}
